#!/usr/bin/env bash
# E-031 — reproduce the frozen LM corpus and its receipt.
#
# The corpus is derived from committed manifests/scripts; it is gitignored (24 MB) and can be
# regenerated byte-for-byte here. The receipt pins every input and the output hash. T/A and every
# dev/test manifest are explicit exclusions; the freezer refuses exact normalized overlap.
set -euo pipefail
cd "$(dirname "$0")/../.."
mkdir -p runs/E-031/frozen
uv run python -m stt.data.freeze_lm_corpus \
  --train-manifest data/manifests/cv_it_train.jsonl \
  --train-manifest data/manifests/mls_it_train.jsonl \
  --train-manifest data/manifests/ls_en_train.jsonl \
  --train-script recordings/scripts/R-S1.jsonl \
  --train-script recordings/scripts/R-S2.jsonl \
  --train-script recordings/scripts/pool.jsonl \
  --exclude recordings/scripts/T.jsonl \
  --exclude recordings/scripts/A.jsonl \
  --exclude recordings/manifests/T.jsonl \
  --exclude recordings/manifests/T-S2.jsonl \
  --exclude recordings/manifests/A-S1.jsonl \
  --exclude recordings/manifests/A-S2.jsonl \
  --exclude recordings/manifests/A-S3.jsonl \
  --exclude data/manifests/cv_it_dev.jsonl \
  --exclude data/manifests/cv_it_test.jsonl \
  --exclude data/manifests/mls_it_dev.jsonl \
  --exclude data/manifests/mls_it_test.jsonl \
  --exclude data/manifests/ls_en_dev.jsonl \
  --exclude data/manifests/fleurs_it_dev.jsonl \
  --exclude data/manifests/fleurs_it_test.jsonl \
  --exclude data/manifests/fleurs_en_dev.jsonl \
  --exclude data/manifests/fleurs_en_test.jsonl \
  --out runs/E-031/frozen/lm-corpus.jsonl \
  --report runs/E-031/frozen/lm-corpus.receipt.json
